// Validate first: an empty or malformed contact_id must match NO client row (a comparison with '' would match every row whose column is blank).
const raw = String($('Trigger').first().json.contact_id || '').trim();
const ok = /^(tg:\d{1,20}|wa:\+\d{1,20})$/.test(raw);
const formula = ok
  ? (raw.startsWith('tg:') ? "{telegram_chat_id}='" + raw.slice(3) + "'" : "{phone}='" + raw.slice(3) + "'")
  : "{client_id}='__no_such_client__'";
return [{ json: { formula } }];

// The decision is made here, not by the model. request_cancel does NOT cancel anything: it checks that the visit is a live,
// future visit of THIS client (the same rules as cancel_booking), records a pending cancellation on the row
// (cancel_expires_at = now + Settings.pending_ttl_min) and says whether cancelling it now would be late
// (Settings.cancellation_hours, the rule cancel_booking applies). WF-1 then asks the client from the row; only the
// client's YES makes WF-1 run cancel_booking. The status is never changed here.
const s = ($('Settings').first().json || {}).fields;
if (!s) throw new Error('request_cancel: the Settings table has no row');
const num = (v) => (v === null || v === undefined || String(v).trim() === '') ? NaN : Number(v);
const hrs = num(s.cancellation_hours);
if (!Number.isFinite(hrs) || hrs < 0) throw new Error('request_cancel: Settings.cancellation_hours must be a number >= 0, got ' + JSON.stringify(s.cancellation_hours));
const ttl = num(s.pending_ttl_min);
if (!Number.isFinite(ttl) || ttl <= 0) throw new Error('request_cancel: Settings.pending_ttl_min must be a positive number, got ' + JSON.stringify(s.pending_ttl_min));
const want = String($('Trigger').first().json.appt_id || '').trim();
const valid = /^A-[0-9A-Z-]{1,40}$/.test(want);
const reject = (verdict) => [{ json: { action: 'reject', verdict, appt_id: valid ? want : '' } }];
if (!valid) return reject('NOT_FOUND');
const ar = $('Appointment').first().json || {};   // the whole record: ar.id is the Appointments record id, the columns are in ar.fields
const a = ar.fields || {};
if (!ar.id || a.appt_id !== want) return reject('NOT_FOUND');
const c = $('Client').first().json || {};
const cid = (c.fields || {}).client_id;
if (!c.id || !cid || a.client_id !== cid) return reject('NOT_YOURS');
// Only a booking is cancelled this way. A pending proposal is not a booking (it lapses on its own after pending_ttl_min);
// cancelled, late_cancel, no_show and done are history.
if (!['booked', 'reminded', 'confirmed'].includes(a.status)) return reject('NOT_FOUND');
const start = DateTime.fromISO(String(a.start_iso || ''));
if (!start.isValid) throw new Error('request_cancel: appointment ' + want + ' has an unreadable start_iso ' + JSON.stringify(a.start_iso));
// A visit that has already started is history (done or a no-show), not something to cancel: nothing is recorded.
if (start <= DateTime.utc()) return reject('NOT_FOUND');
const late = start.diff(DateTime.utc(), 'hours').hours < hrs;
return [{ json: { action: 'ask', rec_id: ar.id, appt_id: want, verdict: (late ? 'LATE_CANCEL_PENDING ' : 'CANCEL_PENDING ') + want,
  cancel_expires_at: DateTime.utc().plus({ minutes: ttl }).toISO() } }];
